func NewListGatewayErrorResponseBody(res *goa.ServiceError) *ListGatewayErrorResponseBody {
	body := &ListGatewayErrorResponseBody{
		Name:      res.Name,
		ID:        res.ID,
		Message:   res.Message,
		Temporary: res.Temporary,
		Timeout:   res.Timeout,
		Fault:     res.Fault,
	}
	return body
}

// NewGetSettingsPayload builds a mcpFeedback service getSettings endpoint
// payload.
func NewGetSettingsPayload(mcpServerID string, sessionToken *string, apikeyToken *string, projectSlugInput *string) *mcpfeedback.GetSettingsPayload {
	v := &mcpfeedback.GetSettingsPayload{}
	v.McpServerID = mcpServerID
	v.SessionToken = sessionToken
	v.ApikeyToken = apikeyToken
	v.ProjectSlugInput = projectSlugInput

	return v
}

// NewUpdateSettingsPayload builds a mcpFeedback service updateSettings
// endpoint payload.
func NewUpdateSettingsPayload(body *UpdateSettingsRequestBody, sessionToken *string, apikeyToken *string, projectSlugInput *string) *mcpfeedback.UpdateSettingsPayload {
	v := &mcpfeedback.UpdateSettingsPayload{
		McpServerID:     *body.McpServerID,
		Enabled:         *body.Enabled,
		ToolName:        body.ToolName,
		ToolDescription: body.ToolDescription,
		ExpectedVersion: body.ExpectedVersion,
	}
	v.SessionToken = sessionToken
	v.ApikeyToken = apikeyToken
	v.ProjectSlugInput = projectSlugInput

	return v
}

// NewListPayload builds a mcpFeedback service list endpoint payload.
func NewListPayload(mcpServerID string, severity *string, toolName *string, cursor *string, limit int, sessionToken *string, apikeyToken *string, projectSlugInput *string) *mcpfeedback.ListPayload {
	v := &mcpfeedback.ListPayload{}
	v.McpServerID = mcpServerID
	if severity != nil {
		tmpseverity := types.McpFeedbackSeverity(*severity)
		v.Severity = &tmpseverity
	}
	v.ToolName = toolName
	v.Cursor = cursor
	v.Limit = limit
	v.SessionToken = sessionToken
	v.ApikeyToken = apikeyToken
	v.ProjectSlugInput = projectSlugInput

	return v
}

// ValidateUpdateSettingsRequestBody runs the validations defined on
// UpdateSettingsRequestBody
func ValidateUpdateSettingsRequestBody(body *UpdateSettingsRequestBody) (err error) {
	if body.McpServerID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("mcp_server_id", "body"))
	}
	if body.Enabled == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("enabled", "body"))
	}
	if body.McpServerID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.mcp_server_id", *body.McpServerID, goa.FormatUUID))
	}
	if body.ToolName != nil {
		err = goa.MergeErrors(err, goa.ValidatePattern("body.tool_name", *body.ToolName, "^[A-Za-z0-9_-]+$"))
	}
	if body.ToolName != nil {
		if utf8.RuneCountInString(*body.ToolName) > 64 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.tool_name", *body.ToolName, utf8.RuneCountInString(*body.ToolName), 64, false))
		}
	}
	if body.ToolDescription != nil {
		if utf8.RuneCountInString(*body.ToolDescription) > 2000 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.tool_description", *body.ToolDescription, utf8.RuneCountInString(*body.ToolDescription), 2000, false))
		}
	}
	return
}
